import { createRequire } from "node:module";
const require = createRequire("/home/mvhenten/development/reader/package.json");
const { chromium } = require("playwright-core");
const out = "/home/mvhenten/development/.tmp/stallion-wire";
const url = "http://100.104.44.51:5173/b/default";
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
const errors = [];
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
page.on("pageerror", (e) => errors.push(String(e)));
await page.goto(url);
await page.waitForSelector("canvas");
await page.evaluate(() => localStorage.clear());
const countStrokes = () => page.evaluate(() => new Promise((resolve, reject) => {
  const req = indexedDB.open("stallion");
  req.onerror = () => reject(req.error);
  req.onsuccess = () => {
    const db = req.result;
    const c = db.transaction("objects").objectStore("objects").count();
    c.onsuccess = () => { resolve(c.result); db.close(); };
  };
}));
const before = await countStrokes();
const draw = async (x, y) => {
  await page.mouse.move(x, y); await page.mouse.down();
  for (let i = 1; i <= 20; i++) await page.mouse.move(x + i * 12, y + Math.sin(i / 3) * 40);
  await page.mouse.up();
};
await draw(300, 350);
await draw(400, 500);
await page.waitForTimeout(400);
await page.screenshot({ path: `${out}/1-drawn.png` });
await page.mouse.move(600, 400);
for (let i = 0; i < 5; i++) await page.mouse.wheel(0, -120);
await page.waitForTimeout(400);
await page.screenshot({ path: `${out}/2-zoomed.png` });
const afterDraw = await countStrokes();
await page.reload();
await page.waitForSelector("canvas");
await page.waitForTimeout(800);
await page.screenshot({ path: `${out}/3-reloaded.png` });
const afterReload = await countStrokes();
const status = await page.getAttribute(".status", "aria-label");
const connection = await page.getAttribute(".status", "data-connection");
const alert = await page.locator(".error").count();
const pixels = await page.evaluate(() => {
  const c = document.querySelector("canvas"); const ctx = c.getContext("2d");
  const d = ctx.getImageData(0, 0, c.width, c.height).data; let n = 0;
  for (let i = 3; i < d.length; i += 4) if (d[i] > 0) n++; return n;
});
console.log(JSON.stringify({ before, afterDraw, afterReload, status, connection, alert, paintedPixelsAfterReload: pixels, errors }, null, 1));
await browser.close();
EOF
cd ~/development/.tmp/stallion-wire && timeout 120 node check.mjs

